              'Turistnemnda ved Lake Bled (LBTB) administrerer 1,27 mill. årlige besøkende til Slovenias mest ikoniske innsjø — en UNESCO Global Geopark. I 2023 avdekket vannkvalitetstesting en 14 % økning i nivåene av mikroplast, tilskrevet lekkasje av motorbåtdrivstoff og slitende skrogmaling fra leiebåter. Direktør for bærekraftig turisme Dr. Ana Kovacic var under press fra Triglav nasjonalpark-myndigheten om å redusere motoriserte farkoster med 60 % innen 2026, eller risikere å miste UNESCO-statusen. Innsjøens 6 km lange omkrets og gjennomsnittsdybde på 30,2 m gjorde den ideell for vannsport uten motor, men eksisterende utleieoperatører hadde investert 2,3 mill. EUR i motorbåtflåter.',
