            background:
              'Mote Marine Laboratorys program for fiskeri og akvakultur overvåker ålegrasdekning, vannkvalitet og utbredelse av manat (Trichechus manatus latirostris) over 80 kvadratmiles av Sarasota Bay som en del av Sarasota Bay Estuary Program (SBEP). Seniorforskeren dr. Isaac Torres sto overfor et dilemma: laboratoriets 22 fots Parker-båter (115 hk utenbordsmotorer) var effektive til kartlegging i stor skala, men deres 3 fots dypgang stengte dem ute fra grunne ålegrasenger (dybder under 1,5 fot), og propellskader var dokumentert å ha skadet 0,4 % av de prøvetatte ålegrasfeltene i 2023. Laboratoriets kajakkflåte for 4 personer var for treg i forhold til begrensningene i tidvannsvinduene og manglet muligheter for utstyrsmontasje. Torres trengte en plattform med liten dypgang og uten propell som kunne bære en YSI EXO2-sonde for flere parametre og et undervannskamerastativ, og håndtere 2 forskere med prøvetakingsutstyr gjennom 8 timer lange overvåkingsdager.',
            goal: 'Å etablere en lydløs SUP-overvåkingsflåte med 15 brett som dekker 120 overvåkingsstasjoner i Sarasota Bay, uten propellpåvirkning på ålegraset og med 30 % flere stasjoner per dag enn med motorbåtoperasjoner.',
