            background:
              'Paws & Paddle var en raskt voksende britisk merkevare for kjæledyrslivsstil, grunnlagt av tidligere veterinærsykepleier Emma Thornton i 2019, med premium hundehalsbånd, hundesenger og friluftsutstyr og 4,2 mill. GBP i årlig omsetning. Det britiske markedet for kjæledyrprodukter var verdsatt til 8 mrd. GBP, 34 % av britiske husholdninger eide hund, og Emma oppdaget et hull i markedet: ingen større kjæledyrmerkevare tilbød vannsportsutstyr for hunder, til tross for den ekspanderende «hundevennlig eventyr»-trenden i sosiale medier (#dogpaddle hadde 430 mill. visninger på TikTok). Emmas team hadde sterke forbindelser til 340 britiske kjæledyrbutikker og over 50 friluftsbutikker, men trengte en produksjonspartner som kunne utvikle SUP-brett spesifikt designet for hundebruk med riktige sikkerhetsfunksjoner og testing.',
            goal: 'Skape en hundevennlig SUP-linje med 3 modeller («Paws & Paddle Adventure»), sikre plassering i over 200 britiske butikklokasjoner i løpet av 12 måneder og oppnå 1,5 mill. GBP i engrossalg det første året med 52 % margin.',
