            goal: 'Å lansere en crowdfundet SUP-merkevare med direktesalg til forbruker, kalt «Driftcraft», med en første produksjonsserie på 500 brett, nå et finansieringsmål på 150 000 GBP i løpet av 45 dager og samtidig beholde full kreativ og operasjonell kontroll.',
