              'Mara Jankovic (41) grunnla «Reef & River Expeditions» i 2016 og drev guidete SUP-turer på Great Barrier Reef og Mulgrave-elven. Innen 2023 var flåten hennes på 45 leiebrett (kjøpt fra tre ulike kinesiske importører) i ferd med å svikte: delaminering hadde rammet 12 brett i løpet av 18 måneder, og inkonsistente oppgitte flyteevner forvirret guidene hennes. Hun brukte 18 000 AUD årlig på utskifting og reparasjoner. Mara ønsket et brett som kunne tåle tropisk sol, saltvann og hyppig bruk av nybegynnere blant turistene, med vekt på opptil 120 kg.',
